package dev.hoi.client.map;

import com.mojang.blaze3d.platform.InputConstants;
import dev.hoi.client.ClientCampaignHud;
import dev.hoi.client.screen.ScreenMapCursor;
import dev.hoi.protocol.*;
import dev.hoi.protocol.ProtocolCommanderHud.*;
import java.nio.file.*;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.input.*;

public final class MapCommanderBranchTheatersTest {
    private MapCommanderBranchTheatersTest() {}
    private static MapCommanderPanels.Hit hit(String icon){return MapCommanderPanels.hits().stream().filter(h->h.icon().equals(icon)).findFirst().orElseThrow(()->new AssertionError("Missing theater hit "+icon));}
    private static void click(String icon,int button){var h=hit(icon);var screen=net.minecraft.client.Minecraft.getInstance().gui.screen();var event=new MouseButtonEvent(h.x()+h.w()/2.,h.y()+h.h()/2.,new MouseButtonInfo(button,0));if(!screen.mouseClicked(event,false))throw new AssertionError("Theater input not consumed");screen.mouseReleased(event);}
    private static void revision(){var c=MapCommanderOrders.currentContext();MapCommanderOrders.accept(new ProtocolCommanderOrders.Context(c.token(),c.revision()+1,c.country(),c.dimension(),""));}
    private static void scroll(ClientGameTestContext game,int direction){game.runOnClient(client->{for(int n=0;n<24;n++)if(!client.gui.screen().mouseScrolled(client.getWindow().getGuiScaledWidth()-30,90,0,direction))throw new AssertionError("Theater wheel input not consumed");});game.waitTicks(2);}
    private static View currentView(){try{var field=MapCommanderHud.class.getDeclaredField("view");field.setAccessible(true);return (View)field.get(null);}catch(ReflectiveOperationException error){throw new AssertionError(error);}}
    private static void accept(View source){var client=net.minecraft.client.Minecraft.getInstance();MapCommanderHud.accept(new View(source.country(),client.level.dimension().identifier().toString(),source.branch(),source.cards(),source.wings(),true,source.theaters()));}
    private static View disabled(View source){var theaters=source.theaters().stream().map(t->new Theater(t.id(),t.name(),t.divisions(),t.groups(),t.armies(),t.warnings(),t.controls().stream().map(c->new Control(c.id(),c.icon(),c.tooltip(),false,c.request())).toList(),t.fleets(),t.reserves(),t.wings(),t.priority(),t.ships())).toList();return new View(source.country(),source.dimension(),source.branch(),source.cards(),source.wings(),true,theaters);}
    private static void command(List<ProtocolCommanderOrders.Command> commands,String action,List<String> selection){if(commands.size()!=1||!commands.getFirst().action().equals(action)||!commands.getFirst().selection().equals(selection)||!commands.getFirst().rays().isEmpty())throw new AssertionError("Wrong theater command: "+commands);commands.clear();revision();}
    public static void run(ClientGameTestContext game,ProtocolMenuView menu) throws java.io.IOException {
        String directory=System.getenv("HOI_COMMANDER_PREVIEW");if(directory==null)throw new AssertionError("HOI_COMMANDER_PREVIEW must point to authoritative theater fixtures");
        for(String branch:List.of("navy","air")){
            var source=new Snapshot(Files.readString(Path.of(directory,"kor-command-panel-"+branch+"-theaters.json"))).view();boolean navy=branch.equals("navy");String prefix=navy?"NAVAL_THEATER":"AIR_THEATER";var first=source.theaters().getFirst();var second=source.theaters().get(1);
            for(int[] size:List.of(new int[]{2560,1440},new int[]{1280,720})){
                var commands=new ArrayList<ProtocolCommanderOrders.Command>();game.getInput().resizeWindow(size[0],size[1]);game.runOnClient(client->{client.options.guiScale().set(2);MapCommanderHud.reset();MapUnitHud.reset();ClientCampaignHud.accept(ProtocolHudPayloads.State.of("KOR",menu.hud()));accept(source);MapCommanderOrders.commandObserver=commands::add;MapCommanderOrders.selectionObserver=ignored->{};MapCommanderOrders.accept(new ProtocolCommanderOrders.Context(UUID.randomUUID().toString(),1,source.country(),client.level.dimension().identifier().toString(),""));});game.setScreen(ScreenMapCursor::new);game.getInput().setCursorPos(20,60);game.waitTicks(3);
                game.runOnClient(client->{if(!MapCommanderPanels.commandSelection().isEmpty())throw new AssertionError("Theaters must not auto-select units");for(var h:MapCommanderPanels.hits())if(h.icon().startsWith("theater_")&&(h.x()<0||h.y()<0||h.x()+h.w()>client.getWindow().getGuiScaledWidth()||h.y()+h.h()>client.getWindow().getGuiScaledHeight()))throw new AssertionError("Theater hit outside viewport");});
                game.takeScreenshot("hoi-"+branch+"-theaters-unselected-"+size[0]+"x"+size[1]+"-gui2");
                if(navy){game.runOnClient(client->{var h=MapCommanderPanels.hits().stream().filter(value->value.icon().equals("theater_fleet/"+first.fleets().getFirst())).max(Comparator.comparingInt(MapCommanderPanels.Hit::y)).orElseThrow();var event=new MouseButtonEvent(h.x()+5,h.y()+h.h()/2.,new MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,0));client.gui.screen().mouseClicked(event,false);client.gui.screen().mouseReleased(event);});game.waitTicks(2);game.runOnClient(client->{if(!MapCommanderPanels.selectedCards().equals(Set.of(first.fleets().getFirst())))throw new AssertionError("Only the first fleet must be selected");});game.takeScreenshot("hoi-navy-theaters-first-selected-"+size[0]+"x"+size[1]+"-gui2");game.runOnClient(client->MapCommanderPanels.closeSelection());game.waitTicks(2);}
                scroll(game,-1);game.runOnClient(client->{click("theater_create",InputConstants.MOUSE_BUTTON_LEFT);if(!commands.isEmpty())throw new AssertionError("Empty creation must be disabled");});game.takeScreenshot("hoi-"+branch+"-theaters-scrolled-"+size[0]+"x"+size[1]+"-gui2");scroll(game,1);
                game.runOnClient(client->click("theater_assign/"+first.id(),InputConstants.MOUSE_BUTTON_LEFT));game.waitTicks(2);
                game.runOnClient(client->{if(navy){var expected=new HashSet<>(first.fleets());expected.addAll(first.reserves());if(!MapCommanderPanels.selectedCards().equals(expected))throw new AssertionError("Navy theater selection leaked");}else if(!MapCommanderPanels.selectedWingIds().equals(Set.copyOf(first.wings())))throw new AssertionError("Air theater selection leaked");if(!commands.isEmpty())throw new AssertionError("Selection must stay local");});
                game.takeScreenshot("hoi-"+branch+"-theaters-selected-"+size[0]+"x"+size[1]+"-gui2");
                var assign=game.computeOnClient(client->hit("theater_assign/"+first.id()));game.getInput().setCursorPos((assign.x()+assign.w()-3)*2,(assign.y()+3)*2);game.waitTicks(2);game.takeScreenshot("hoi-"+branch+"-theaters-tooltip-"+size[0]+"x"+size[1]+"-gui2");game.getInput().setCursorPos(20,60);
                game.runOnClient(client->{click("theater_assign/"+second.id(),InputConstants.MOUSE_BUTTON_RIGHT);click("theater_assign/"+second.id(),InputConstants.MOUSE_BUTTON_RIGHT);var expected=new ArrayList<String>();expected.add("target/"+second.id());expected.addAll(navy?first.fleets():first.wings());command(commands,prefix+"/ASSIGN",expected);if(!currentView().theaters().equals(source.theaters()))throw new AssertionError("Client changed authoritative theaters before response");});game.waitTicks(2);
                scroll(game,-1);game.runOnClient(client->{click("theater_create",InputConstants.MOUSE_BUTTON_RIGHT);if(!commands.isEmpty())throw new AssertionError("Create right click must be inert");click("theater_create",InputConstants.MOUSE_BUTTON_LEFT);click("theater_create",InputConstants.MOUSE_BUTTON_LEFT);command(commands,prefix+"/CREATE",navy?first.fleets():first.wings());});scroll(game,1);
                game.runOnClient(client->{if(MapCommanderPanels.hits().stream().anyMatch(h->h.icon().startsWith("theater_collapse/")))throw new AssertionError("Theater titles must not collapse");});
                if(navy){
                    for(var theater:List.of(first,second)){
                        var alert=theater.controls().stream().filter(c->c.id().equals("NAVAL_THEATER_ALERT/"+theater.priority())).findFirst().orElseThrow();
                        game.runOnClient(client->{var h=hit("theater_alert/"+theater.id());if(!h.tip().equals(alert.tooltip()))throw new AssertionError("Alert tooltip changed");click(h.icon(),InputConstants.MOUSE_BUTTON_RIGHT);if(!commands.isEmpty())throw new AssertionError("Alert right click must be inert");click(h.icon(),InputConstants.MOUSE_BUTTON_LEFT);click(h.icon(),InputConstants.MOUSE_BUTTON_LEFT);command(commands,"NAVAL_THEATER/ALERT/"+(theater.priority().equals("HIGH")?"NORMAL":"HIGH"),List.of(theater.id()));if(!currentView().theaters().equals(source.theaters()))throw new AssertionError("Alert priority updated before response");});
                        var alertHit=game.computeOnClient(client->hit("theater_alert/"+theater.id()));game.getInput().setCursorPos((alertHit.x()+alertHit.w()/2.)*2,(alertHit.y()+alertHit.h()/2.)*2);game.waitTicks(2);game.takeScreenshot("hoi-navy-theaters-alert-"+theater.priority().toLowerCase(Locale.ROOT)+"-"+size[0]+"x"+size[1]+"-gui2");game.getInput().setCursorPos(20,60);
                    }
                }
                if(navy){game.runOnClient(client->click("theater_reserves/"+first.id(),InputConstants.MOUSE_BUTTON_LEFT));game.waitTicks(2);scroll(game,-1);game.runOnClient(client->{if(!MapCommanderPanels.selectedCards().equals(Set.copyOf(first.reserves())))throw new AssertionError("Reserve row must select only reserves");click("theater_create",InputConstants.MOUSE_BUTTON_LEFT);click("theater_assign/"+second.id(),InputConstants.MOUSE_BUTTON_RIGHT);if(!commands.isEmpty())throw new AssertionError("Reserve fleets cannot move or create theaters");});scroll(game,1);}
                else{
                    var priorityHit=game.computeOnClient(client->hit("theater_priority/"+first.id()+"/HIGH"));var priorityControl=first.controls().stream().filter(c->c.id().equals("AIR_THEATER_PRIORITY/HIGH")).findFirst().orElseThrow();if(!priorityHit.tip().equals(priorityControl.tooltip()))throw new AssertionError("Replacement priority tooltip changed");game.getInput().setCursorPos((priorityHit.x()+priorityHit.w()/2.)*2,(priorityHit.y()+priorityHit.h()/2.)*2);game.waitTicks(2);game.takeScreenshot("hoi-air-theaters-priority-tooltip-"+size[0]+"x"+size[1]+"-gui2");game.getInput().setCursorPos(20,60);
                    game.runOnClient(client->{click("theater_priority/"+first.id()+"/"+first.priority(),InputConstants.MOUSE_BUTTON_LEFT);if(!commands.isEmpty())throw new AssertionError("Current priority must be disabled");click("theater_priority/"+first.id()+"/HIGH",InputConstants.MOUSE_BUTTON_LEFT);click("theater_priority/"+first.id()+"/HIGH",InputConstants.MOUSE_BUTTON_LEFT);command(commands,"AIR_THEATER/PRIORITY/HIGH",List.of(first.id()));if(!currentView().theaters().getFirst().priority().equals(first.priority()))throw new AssertionError("Priority updated optimistically");var group=source.cards().stream().filter(c->c.role()==Mode.ARMY_GROUP).findFirst().orElseThrow();MapCommanderPanels.select(group.id(),false);var expected=MapCommanderPanels.attachedWings(source,Set.of(group.id()));if(expected.size()!=2||!MapCommanderPanels.selectedWingIds().equals(Set.copyOf(expected)))throw new AssertionError("Army-group card must collect both attached wings independently of theaters");});game.waitTicks(2);game.takeScreenshot("hoi-air-theaters-army-group-"+size[0]+"x"+size[1]+"-gui2");
                }
                game.runOnClient(client->click("theater_settings/"+second.id(),InputConstants.MOUSE_BUTTON_LEFT));game.waitTicks(2);game.takeScreenshot("hoi-"+branch+"-theaters-settings-"+size[0]+"x"+size[1]+"-gui2");
                game.runOnClient(client->{click("theater_disband",InputConstants.MOUSE_BUTTON_LEFT);click("theater_disband",InputConstants.MOUSE_BUTTON_LEFT);command(commands,prefix+"/DISBAND",List.of(second.id()));MapCommanderTheaters.closeSettings();MapCommanderPanels.closeSelection();});game.waitTicks(2);
                game.runOnClient(client->{if(!MapCommanderPanels.commandSelection().isEmpty())throw new AssertionError("Theater deselection retained commands");accept(disabled(source));});game.waitTicks(2);
                game.runOnClient(client->{click("theater_assign/"+first.id(),InputConstants.MOUSE_BUTTON_LEFT);click("theater_assign/"+second.id(),InputConstants.MOUSE_BUTTON_RIGHT);if(!commands.isEmpty()||!MapCommanderPanels.commandSelection().isEmpty())throw new AssertionError("Disabled controls changed selection or sent commands");});scroll(game,-1);game.runOnClient(client->{click("theater_create",InputConstants.MOUSE_BUTTON_LEFT);if(!commands.isEmpty())throw new AssertionError("Disabled creation sent a command");});scroll(game,1);game.runOnClient(client->click("theater_settings/"+second.id(),InputConstants.MOUSE_BUTTON_LEFT));game.waitTicks(2);
                game.runOnClient(client->{click("theater_disband",InputConstants.MOUSE_BUTTON_LEFT);if(navy)click("theater_alert/"+first.id(),InputConstants.MOUSE_BUTTON_LEFT);if(!commands.isEmpty())throw new AssertionError("Disabled control sent a command");});game.takeScreenshot("hoi-"+branch+"-theaters-disabled-"+size[0]+"x"+size[1]+"-gui2");
                game.runOnClient(client->{MapCommanderTheaters.closeSettings();accept(source);});game.waitTicks(2);game.runOnClient(client->click("theater_assign/"+first.id(),InputConstants.MOUSE_BUTTON_LEFT));game.waitTicks(2);
                game.runOnClient(client->{MapCommanderOrders.reset();if(navy)click("theater_alert/"+first.id(),InputConstants.MOUSE_BUTTON_LEFT);if(!commands.isEmpty())throw new AssertionError("Revoked session sent a command");});scroll(game,-1);game.runOnClient(client->{click("theater_create",InputConstants.MOUSE_BUTTON_LEFT);if(!commands.isEmpty())throw new AssertionError("Revoked session created a theater");MapCommanderOrders.commandObserver=null;MapCommanderOrders.selectionObserver=null;MapCommanderHud.reset();MapUnitHud.reset();});
            }
        }
    }
}
